export const blurIcon = "blur(2px)";

export function flipTransform(side: "top" | "bottom" | "left" | "right") {
  const rotate =
    side === "top"
      ? "rotateX(-20deg)"
      : side === "bottom"
        ? "rotateX(20deg)"
        : side === "left"
          ? "rotateY(20deg)"
          : "rotateY(-20deg)";
  return `perspective(500px) ${rotate} scale(0.8)`;
}

export function uprightTransform(side: "top" | "bottom" | "left" | "right") {
  const rotate = side === "left" || side === "right" ? "rotateY(0deg)" : "rotateX(0deg)";
  return `perspective(500px) ${rotate} scale(1)`;
}

"use client";

import * as React from "react";
import { motion, useInView } from "motion/react";
import { cn } from "@/lib/utils";
import { useReduceMotion } from "./motion";

export type MotionGridProps = Omit<React.ComponentProps<"div">, "onChange"> & {
  count?: number;
  columns?: number;
  dotSize?: number;
  gap?: number;
  speed?: number;
  stagger?: number;
  pauseOnHover?: boolean;
  dotClassName?: string;
};

export function MotionGrid({
  count = 35,
  columns = 7,
  dotSize = 8,
  gap = 10,
  speed = 1.4,
  stagger = 0.07,
  pauseOnHover = true,
  dotClassName,
  className,
  onPointerEnter,
  onPointerLeave,
  style,
  ...props
}: MotionGridProps) {
  const reduce = useReduceMotion();
  const ref = React.useRef<HTMLDivElement>(null);
  const inView = useInView(ref, { margin: "120px 0px" });
  const [paused, setPaused] = React.useState(false);
  const total = Math.max(1, Math.round(count));
  const cols = Math.max(1, Math.round(columns));

  return (
    <div
      ref={ref}
      data-slot="motion-grid"
      aria-hidden="true"
      className={cn("grid w-fit", className)}
      style={{
        gridTemplateColumns: `repeat(${cols}, minmax(0, 1fr))`,
        gap,
        ...style,
      }}
      onPointerEnter={(event) => {
        onPointerEnter?.(event);
        if (pauseOnHover) setPaused(true);
      }}
      onPointerLeave={(event) => {
        onPointerLeave?.(event);
        if (pauseOnHover) setPaused(false);
      }}
      {...props}
    >
      {Array.from({ length: total }, (_, index) => {
        const row = Math.floor(index / cols);
        const column = index % cols;
        const delay = (row + column) * stagger;
        const resting = reduce || paused || !inView;
        return (
          <motion.span
            key={index}
            className={cn("rounded-full bg-foreground", dotClassName)}
            style={{ width: dotSize, height: dotSize }}
            animate={
              resting
                ? { scale: 1, opacity: paused ? 0.35 : 0.55 }
                : {
                    scale: [0.65, 1, 0.65],
                    opacity: [0.3, 1, 0.3],
                  }
            }
            transition={
              resting
                ? { duration: reduce ? 0 : 0.2 }
                : {
                    duration: speed,
                    repeat: Infinity,
                    delay,
                    ease: "easeInOut",
                  }
            }
          />
        );
      })}
    </div>
  );
}

"use client";

import { useReducedMotion } from "motion/react";
import { useSyncExternalStore } from "react";

const subscribe = () => () => {};

export function useHydratedReducedMotion() {
  const reduce = useReducedMotion() ?? false;
  const mounted = useSyncExternalStore(
    subscribe,
    () => true,
    () => false,
  );
  return mounted ? reduce : false;
}
